import { useEffect, useState } from "react";
import ProgressBar from "../components/ProgressBar";
import ProgressChart from "../components/ProgressChart";

export default function ProgressPage() {
  const [metrics, setMetrics] = useState({});
  const [streak, setStreak] = useState(0);
  const [xp, setXP] = useState(0);
  const [level, setLevel] = useState(1);
  const [badges, setBadges] = useState([]);
  const [completedDays, setCompletedDays] = useState([]);

  useEffect(() => {
    const quizScore = parseInt(localStorage.getItem("quizScore") || "0");
    const totalQuestions = parseInt(localStorage.getItem("totalQuestions") || "1");
    const quiz = Math.round((quizScore / totalQuestions) * 100);

    const completed = parseInt(localStorage.getItem("lastCompletedCount") || "0");
    const totalTasks = parseInt(localStorage.getItem("lastTotalTasks") || "1");
    const tasks = Math.round((completed / totalTasks) * 100);

    const completedDays = JSON.parse(localStorage.getItem("completedDays") || "[]");
    const currentDay = parseInt(localStorage.getItem("currentDay") || "1");

    const consistency = Math.round((completedDays.length / currentDay) * 100);

    // 🔥 Streak
    let currentStreak = 0;
    for (let i = completedDays.length - 1; i >= 0; i--) {
      if (completedDays[i] === currentDay - currentStreak - 1) currentStreak++;
      else break;
    }

    // 🎮 XP + Level
    const totalXP = parseInt(localStorage.getItem("xp") || "0");
    const level = Math.floor(totalXP / 100) + 1;

    // 🏅 Badges
    const getBadges = () => {
      const b = [];
      if (currentStreak >= 3) b.push("🔥 3 Day Streak");
      if (currentStreak >= 7) b.push("🚀 7 Day Warrior");
      if (quiz >= 80) b.push("🧠 Quiz Master");
      if (consistency >= 70) b.push("📅 Consistency King");
      if (totalXP >= 500) b.push("🏆 Level Grinder");
      return b;
    };

    setMetrics({ quiz, tasks, consistency });
    setStreak(currentStreak);
    setXP(totalXP);
    setLevel(level);
    setBadges(getBadges());
    setCompletedDays(completedDays);
  }, []);

  return (
    <div className="space-y-10">

  {/* 🔥 HERO HEADER */}
  <div className="rounded-[2rem] border border-slate-300 bg-gradient-to-br from-white via-blue-50 to-teal-50 p-8 shadow-lg shadow-slate-200/50 dark:border-slate-600 dark:from-slate-800 dark:to-slate-800">
    <h2 className="text-4xl font-bold text-slate-900 dark:text-slate-50">
      📊 Progress Dashboard
    </h2>
    <p className="mt-3 text-slate-600 dark:text-slate-300">
      Track your growth, stay consistent, and level up your skills 🚀
    </p>
  </div>

  {/* 🎮 XP + LEVEL CARDS */}
  <div className="grid gap-6 md:grid-cols-2">
    <div className="rounded-[2rem] border border-slate-300 bg-gradient-to-br from-purple-100 to-purple-50 p-6 shadow-lg hover:scale-[1.02] transition dark:border-slate-600 dark:from-slate-700 dark:to-slate-700">
      <p className="text-sm text-slate-600 dark:text-slate-300">Total XP</p>
      <h3 className="mt-2 text-4xl font-bold text-purple-700 dark:text-purple-300">
        {xp}
      </h3>
      <p className="text-sm mt-2 text-slate-500">Keep earning XP daily</p>
    </div>

    <div className="rounded-[2rem] border border-slate-300 bg-gradient-to-br from-green-100 to-green-50 p-6 shadow-lg hover:scale-[1.02] transition dark:border-slate-600 dark:from-slate-700 dark:to-slate-700">
      <p className="text-sm text-slate-600 dark:text-slate-300">Your Level</p>
      <h3 className="mt-2 text-4xl font-bold text-green-700 dark:text-green-300">
        Level {level}
      </h3>
      <p className="text-sm mt-2 text-slate-500">Next level at {level * 100} XP</p>
    </div>
  </div>

  {/* 📈 GRAPH SECTION */}
  <div className="rounded-[2rem] border border-slate-300 bg-gradient-to-br from-white to-blue-50 p-8 shadow-lg dark:border-slate-600 dark:from-slate-800 dark:to-slate-800">
    <h3 className="text-xl font-semibold text-slate-900 dark:text-slate-50">
      📈 Weekly Progress
    </h3>
    <p className="text-sm mt-1 text-slate-600 dark:text-slate-300">
      Your daily consistency and task completion trend
    </p>

    <div className="mt-6">
      <ProgressChart completedDays={completedDays} />
    </div>
  </div>

  {/* 📊 METRICS */}
  <div className="grid gap-6 xl:grid-cols-3">
    {[ 
      { label: "Consistency", value: metrics.consistency },
      { label: "Quiz Mastery", value: metrics.quiz },
      { label: "Task Completion", value: metrics.tasks },
    ].map((item) => (
      <div key={item.label} className="rounded-[2rem] border border-slate-300 bg-gradient-to-br from-white to-blue-50 p-6 shadow-lg hover:shadow-xl transition dark:border-slate-600 dark:from-slate-800 dark:to-slate-800">
        <p className="text-sm text-slate-600 dark:text-slate-400">{item.label}</p>
        <div className="mt-4">
          <ProgressBar label={item.label} value={item.value} />
        </div>
      </div>
    ))}
  </div>

  {/* 🔥 STREAK + MOTIVATION */}
  <div className="grid gap-6 lg:grid-cols-2">

    {/* STREAK */}
    <div className="rounded-[2rem] bg-gradient-to-br from-teal-100 to-blue-100 p-8 shadow-lg dark:from-slate-700 dark:to-slate-700">
      <h3 className="text-xl font-semibold text-slate-900 dark:text-slate-50">
        🔥 Current Streak
      </h3>
      <p className="mt-3 text-5xl font-bold text-teal-900 dark:text-teal-200">
        {streak} days
      </p>
      <p className="mt-3 text-sm text-slate-700 dark:text-slate-300">
        {streak > 0
          ? "You're building momentum. Keep going 🔥"
          : "Start today and build your streak 💪"}
      </p>
    </div>

    {/* MOTIVATION */}
    <div className="rounded-[2rem] bg-gradient-to-br from-yellow-100 to-orange-50 p-8 shadow-lg dark:from-slate-700 dark:to-slate-700">
      <h3 className="text-xl font-semibold text-slate-900 dark:text-slate-50">
        🤖 Smart Recommendation
      </h3>
      <p className="mt-3 text-slate-700 dark:text-slate-300">
        {recommendation}
      </p>
    </div>

  </div>

  {/* 🏅 BADGES */}
  <div className="rounded-[2rem] border border-slate-300 bg-gradient-to-br from-white to-blue-50 p-8 shadow-lg dark:border-slate-600 dark:from-slate-800 dark:to-slate-800">
    <h3 className="text-xl font-semibold text-slate-900 dark:text-slate-50">
      🏅 Achievements
    </h3>
    <p className="mt-1 text-sm text-slate-600 dark:text-slate-400">
      Unlock badges by maintaining consistency and performance
    </p>

    <div className="mt-6 flex flex-wrap gap-4">
      {badges.length > 0 ? (
        badges.map((badge, i) => (
          <div
            key={i}
            className="rounded-full bg-gradient-to-r from-teal-400 to-blue-400 px-5 py-2 text-white font-medium shadow-md"
          >
            {badge}
          </div>
        ))
      ) : (
        <p className="text-slate-500">No badges yet. Start learning 🚀</p>
      )}
    </div>
  </div>

</div>)
}
